vosi:tableset:
{%- for schema in schemas %}

    {{ schema.schema_name }}
    {%- if schema.description %}
    {{ schema.description }}
    {%- endif %}
    {%- for table in schema.tables %}

      {{ table.table_name }}
      {%- if table.description %}
      {{ table.description }}
      {%- endif %}

    {%- endfor %}

{%- endfor %}
